-- 1b. markers left in a 'Pronounced' note
-- 2. glosses
update public.senses s set definition_en = 'short for 姨太太' from public.entries e where s.entry_id = e.id and e.hanzi = '姨太' and s.definition_en = 'short for for 姨太太';
update public.senses s set definition_en = 'short and small; undersized' from public.entries e where s.entry_id = e.id and e.hanzi = '矮嫩' and s.definition_en = 'short for and small; undersized';
update public.senses s set definition_en = 'short for 貓王鳥' from public.entries e where s.entry_id = e.id and e.hanzi = '貓王' and s.definition_en = 'short for for 貓王鳥';
update public.senses s set definition_en = 'short for 大雁鵝' from public.entries e where s.entry_id = e.id and e.hanzi = '雁鵝' and s.definition_en = 'short for for 大雁鵝';
update public.senses s set definition_en = 'short for 鼎邊糊' from public.entries e where s.entry_id = e.id and e.hanzi = '鼎邊' and s.definition_en = 'short for for 鼎邊糊';
